#pragma once

#include <cstddef>

// The data UTS 46 is done from (Idna.h), and Unicode's conformance tests for
// it. IdnaTables.cpp and IdnaTestData.cpp are GENERATED by
// build/generate-idna-tables.py from the Unicode data files under ucd/, which
// it holds to their SHA-256s; edit the generator, never the two files.
// Every table is sorted by its first code point, for a binary search.

namespace HM
{
   namespace IdnaTables
   {
      // The Unicode version the data is of, "18.0.0".
      extern const char *const UnicodeVersion;

      // IdnaMappingTable.txt's statuses. UTS 46 has had no STD3 statuses
      // since Unicode 16.0: UseSTD3ASCIIRules is a validity criterion.
      enum Status
      {
         StatusValid = 0,
         StatusIgnored = 1,
         StatusMapped = 2,
         StatusDeviation = 3,
         StatusDisallowed = 4
      };

      // first..last have status; a mapped code point or a deviation maps to the
      // length code points at MappingData[offset] (a deviation's mapping is
      // used only by Transitional Processing, and may be empty).
      struct MappingRange
      {
         unsigned int first;
         unsigned int last;
         unsigned char status;
         unsigned char length;
         unsigned int offset;
      };

      extern const MappingRange MappingRanges[];
      extern const size_t MappingRangeCount;
      extern const unsigned int MappingData[];

      // first..last have value.
      struct ValueRange
      {
         unsigned int first;
         unsigned int last;
         unsigned char value;
      };

      // Canonical_Combining_Class, where it is not 0.
      extern const ValueRange CombiningClasses[];
      extern const size_t CombiningClassCount;

      // A code point's full canonical decomposition: length code points at
      // DecompositionData[offset]. Hangul syllables are done by arithmetic.
      struct Decomposition
      {
         unsigned int codePoint;
         unsigned int length;
         unsigned int offset;
      };

      extern const Decomposition Decompositions[];
      extern const size_t DecompositionCount;
      extern const unsigned int DecompositionData[];

      // The length of the longest full canonical decomposition (a Hangul
      // syllable's is three): NFC makes a text this many times shorter at most.
      // The generator holds the data to the other things ProcessLabels rests
      // on when it maps a name a label at a time (Idna.cpp).
      extern const unsigned int LongestDecomposition;

      // A primary composite, by the two code points it is composed of.
      struct Composition
      {
         unsigned int first;
         unsigned int second;
         unsigned int composite;
      };

      extern const Composition Compositions[];
      extern const size_t CompositionCount;

      // General_Category Mark (Mn, Mc, Me); value is 1.
      extern const ValueRange Marks[];
      extern const size_t MarkCount;

      // Bidi_Class, where it is not L.
      enum BidiClass
      {
         BidiL = 0, BidiR, BidiAL, BidiEN, BidiES, BidiET, BidiAN, BidiCS, BidiNSM, BidiBN, BidiB, BidiS,
         BidiWS, BidiON, BidiLRE, BidiLRO, BidiRLE, BidiRLO, BidiPDF, BidiLRI, BidiRLI, BidiFSI, BidiPDI
      };

      extern const ValueRange BidiClasses[];
      extern const size_t BidiClassCount;

      // Joining_Type, where it is not U.
      enum JoiningType
      {
         JoiningU = 0, JoiningC, JoiningD, JoiningL, JoiningR, JoiningT
      };

      extern const ValueRange JoiningTypes[];
      extern const size_t JoiningTypeCount;

      // IdnaTestV2.txt's test lines (IdnaTestData.cpp).
      extern const char *const TestLines[];
      extern const size_t TestLineCount;
   }
}
